import React from 'react';
import { DataTable, TableToolbarSearch } from 'carbon-components-react';

const headers = [
  { key: 'protocol', header: 'Protocol' },
  { key: 'port', header: 'Port' },
  { key: 'rule', header: 'Rule' },
  { key: 'attachedGroups', header: 'Attached Groups' },
  { key: 'status', header: 'Status' },
];

const rows = [
  { id: 'a', protocol: 'HTTP', port: 3000, rule: 'Round robin', attachedGroups: 'Kevins VM Groups', status: 'Disabled' },
  { id: 'b', protocol: 'HTTP', port: 443, rule: 'Round robin', attachedGroups: 'Maureens VM Groups', status: 'Starting' },
  { id: 'c', protocol: 'HTTP', port: 80, rule: 'DNS delegation', attachedGroups: 'Andrews VM Groups', status: 'Active' },
];

function App() {
  return (
    <DataTable
      rows={rows}
      headers={headers}
      render={({ rows, headers, getHeaderProps }) => (
        <div>
          <TableToolbarSearch
            role="search"
            // Attempt to add aria-label
            aria-label="Search through table"
          />
          <table>
            <thead>
              <tr>
                {headers.map(header => (
                  <th {...getHeaderProps({ header })}>{header.header}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {rows.map(row => (
                <tr key={row.id}>
                  {row.cells.map(cell => (
                    <td key={cell.id}>{cell.value}</td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    />
  );
}

export default App;
